<body>

<div id="gameContainer">
  <canvas id="table"></canvas>
  <div id="info">Drag on cue ball to aim &amp; shoot</div>
  <div id="pocketed" id="msgBox"></div>
</div>
<div id="controls">
  <button id="resetBtn">Reset / Rack</button>
</div>
<div id="instructions">
  <strong>How to play:</strong><br>
  1. <b>Click and hold</b> on the <b>white cue ball</b>, then <b>drag backward</b> (away from target) to set power.<br>
  2. Release to <b>shoot</b>. Longer drag = harder shot.<br>
  3. Drag a line to see your aim direction. Wait for all balls to stop before shooting again.<br>
  4. Pocket all colored balls! Click <em>Reset / Rack</em> to restore the table.
</div>

<script>
(function() {
"use strict";

// ============ CONFIGURATION ============
const TABLE_W = 900;
const TABLE_H = 500;
const BALL_R = 12;
const CUSHION = 36;
const POCKET_R = 20;
const FRICTION = 0.985;
const MIN_SPEED = 0.05;
const MAX_POWER = 1200;
const SUB_STEPS = 4;
const PLAYFIELD_LEFT = CUSHION + BALL_R;
const PLAYFIELD_TOP = CUSHION + BALL_R;
const PLAYFIELD_RIGHT = TABLE_W - CUSHION - BALL_R;
const PLAYFIELD_BOTTOM = TABLE_H - CUSHION - BALL_R;

// Pocket positions
const POCKETS = [
  { x: CUSHION + 2, y: CUSHION + 2 },
  { x: TABLE_W / 2, y: CUSHION - 2 },
  { x: TABLE_W - CUSHION - 2, y: CUSHION + 2 },
  { x: CUSHION + 2, y: TABLE_H - CUSHION - 2 },
  { x: TABLE_W / 2, y: TABLE_H - CUSHION + 2 },
  { x: TABLE_W - CUSHION - 2, y: TABLE_H - CUSHION - 2 },
];

// Ball colors for rack
const BALL_COLORS = [
  "#e8c17a", // 1 yellow
  "#3355aa", // 2 blue
  "#cc3333", // 3 red
  "#6b4dc3", // 4 purple
  "#ee7722", // 5 orange
  "#228844", // 6 green
  "#8b2252", // 7 maroon
  "#222222", // 8 black
  "#e8c17a", // 9 yellow stripe
  "#3355aa", // 10 blue
  "#cc3333", // 11 red
  "#6b4dc3", // 12 purple
  "#ee7722", // 13 orange
  "#228844", // 14 green
  "#8b2252", // 15 maroon
];

// ============ SIMULATION STATE ============
let balls = [];
let paused = false;
let dragging = false;
let dragStartX = 0, dragStartY = 0;
let dragEndX = 0, dragEndY = 0;
let mouseInCueBall = false;
let anyBallsMoving = false;
let pocketMsgTimer = null;

const canvas = document.getElementById("table");
const ctx = canvas.getContext("2d");
canvas.width = TABLE_W;
canvas.height = TABLE_H;

// ============ RACK SETUP ============
function createRack() {
  const cueX = TABLE_W * 0.25;
  const cueY = TABLE_H / 2;

  // Cue ball
  balls = [{ x: cueX, y: cueY, vx: 0, vy: 0, potted: false, cue: true }];

  // Triangle rack at ~70% of table length
  const startX = TABLE_W * 0.7;
  const startY = TABLE_H / 2;
  const spacing = BALL_R * 2 + 1.5; // slight gap for release

  let idx = 0;
  // 5 rows: 1, 2, 3, 4, 5 balls
  const rows = [1, 2, 3, 4, 5];
  let colorIdx = 0;
  for (let row = 0; row < rows.length; row++) {
    const count = rows[row];
    const xOff = (row) * spacing * Math.sqrt(3) / 2;
    for (let col = 0; col < count; col++) {
      const yOff = (col - (count - 1) / 2) * spacing;
      const bx = startX + xOff;
      const by = startY + yOff;
      balls.push({
        x: bx,
        y: by,
        vx: 0,
        vy: 0,
        potted: false,
        cue: false,
        color: BALL_COLORS[colorIdx % BALL_COLORS.length],
        stripe: colorIdx >= 8
      });
      colorIdx++;
    }
  }
}

// ============ RESET ============
function resetSim() {
  paused = true;
  createRack();
  anyBallsMoving = false;
  document.getElementById("info").textContent = "Drag on cue ball to aim & shoot";
  if (pocketMsgTimer) { clearTimeout(pocketMsgTimer); pocketMsgTimer = null; }
  draw();
  paused = false;
}

// ============ PHYSICS ============
function simulate(dt) {
  const subDt = dt / SUB_STEPS;
  for (let step = 0; step < SUB_STEPS; step++) {
    // Apply friction
    for (const b of balls) {
      if (b.potted) continue;
      let speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
      if (speed > MIN_SPEED) {
        const factor = Math.pow(FRICTION, subDt * 60);
        b.vx *= factor;
        b.vy *= factor;
        // Check if should stop
        speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
        if (speed < MIN_SPEED) {
          b.vx = 0;
          b.vy = 0;
        }
      } else if (speed > 0) {
        b.vx = 0;
        b.vy = 0;
      }
    }

    // Move balls
    for (const b of balls) {
      if (b.potted) continue;
      b.x += b.vx * subDt;
      b.y += b.vy * subDt;
    }

    // Cushion collisions
    for (const b of balls) {
      if (b.potted) continue;
      // Check pockets first - skip cushion collision near pocket areas
      let nearPocket = false;
      for (const p of POCKETS) {
        const dx = b.x - p.x;
        const dy = b.y - p.y;
        if (dx * dx + dy * dy < POCKET_R * POCKET_R) {
          nearPocket = true;
          break;
        }
      }

      if (!nearPocket) {
        if (b.x - BALL_R < PLAYFIELD_LEFT) {
          b.x = PLAYFIELD_LEFT;
          b.vx = -b.vx * 0.85;
        }
        if (b.x + BALL_R > PLAYFIELD_RIGHT) {
          b.x = PLAYFIELD_RIGHT;
          b.vx = -b.vx * 0.85;
        }
        if (b.y - BALL_R < PLAYFIELD_TOP) {
          b.y = PLAYFIELD_TOP;
          b.vy = -b.vy * 0.85;
        }
        if (b.y + BALL_R > PLAYFIELD_BOTTOM) {
          b.y = PLAYFIELD_BOTTOM;
          b.vy = -b.vy * 0.85;
        }
      }

      // Pocket detection
      for (const p of POCKETS) {
        const dx = b.x - p.x;
        const dy = b.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < POCKET_R * 0.6) {
          // Check if already potted
          if (!b.potted) {
            if (b.cue) {
              b.x = TABLE_W * 0.25;
              b.y = TABLE_H / 2;
              b.vx = 0;
              b.vy = 0;
              // Don't set potted for cue ball - respawn it
            } else {
              b.potted = true;
              b.vx = 0;
              b.vy = 0;
              b.x = p.x;
              b.y = p.y;
              showPocketMsg("Ball pocketed!");
            }
          }
        }
      }
    }

    // Ball-to-ball collisions
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        if (a.potted || b.potted) continue;

        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const minDist = BALL_R * 2;

        if (dist < minDist && dist > 0.001) {
          // Normal vector
          const nx = dx / dist;
          const ny = dy / dist;

          // Relative velocity along normal
          const dvx = a.vx - b.vx;
          const dvy = a.vy - b.vy;
          const dvn = dvx * nx + dvy * ny;

          // Only resolve if approaching
          if (dvn > 0) {
            // Elastic collision (equal mass)
            const restitution = 0.95;
            const impulse = dvn * restitution;

            a.vx -= impulse * nx;
            a.vy -= impulse * ny;
            b.vx += impulse * nx;
            b.vy += impulse * ny;
          }

          // Separate overlapping balls
          const overlap = minDist - dist;
          if (overlap > 0) {
            const sepX = overlap * nx / 2 + 0.1;
            const sepY = overlap * ny / 2 + 0.1;
            a.x -= sepX;
            a.y -= sepY;
            b.x += sepX;
            b.y += sepY;
          }
        }
      }
    }
  }

  // Check if all balls stopped
  anyBallsMoving = false;
  for (const b of balls) {
    if (!b.potted && !b.cue) {
      const speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
      if (speed > MIN_SPEED * 2) { anyBallsMoving = true; break; }
    }
  }
}

function state() {
  return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, potted: b.potted, cue: b.cue }));
}

function shoot(vx, vy) {
  for (const b of balls) {
    if (!b.potted && b.cue) {
      b.vx = vx;
      b.vy = vy;
      break;
    }
  }
}

// ============ DRAWING ============
function draw() {
  // Table background
  ctx.fillStyle = "#1a6b30";
  ctx.fillRect(0, 0, TABLE_W, TABLE_H);

  // Felt texture (subtle gradient)
  const feltGrad = ctx.createRadialGradient(TABLE_W / 2, TABLE_H / 2, 50, TABLE_W / 2, TABLE_H / 2, TABLE_W * 0.6);
  feltGrad.addColorStop(0, "#2a8a3e");
  feltGrad.addColorStop(1, "#1a6b30");
  ctx.fillStyle = feltGrad;
  ctx.fillRect(0, 0, TABLE_W, TABLE_H);

  // Rails (wood border)
  const railW = CUSHION + BALL_R;
  ctx.fillStyle = "#5c3a1e";
  ctx.fillRect(0, 0, TABLE_W, railW - BALL_R);
  ctx.fillRect(0, TABLE_H - railW + BALL_R, TABLE_W, railW);
  ctx.fillRect(0, 0, railW - BALL_R, TABLE_H);
  ctx.fillRect(TABLE_W - railW + BALL_R, 0, railW, TABLE_H);

  // Inner rail face
  ctx.fillStyle = "#4a7c3f";
  ctx.fillRect(CUSHION, CUSHION, TABLE_W - CUSHION * 2, TABLE_H - CUSHION * 2);

  // Cushion bumpers (small rounded pads on rails)
  ctx.fillStyle = "#4a7c3f";
  const bumperPositions = [TABLE_W / 2];
  for (const bx of bumperPositions) {
    ctx.beginPath();
    ctx.arc(bx, CUSHION, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(bx, TABLE_H - CUSHION, 8, 0, Math.PI * 2);
    ctx.fill();
  }

  // Pockets
  for (const p of POCKETS) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, POCKET_R, 0, Math.PI * 2);
    ctx.fillStyle = "#111";
    ctx.fill();
    ctx.strokeStyle = "#333";
    ctx.lineWidth = 2;
    ctx.stroke();

    // Pocket inner shadow
    const pGrad = ctx.createRadialGradient(p.x, p.y, POCKET_R * 0.5, p.x, p.y, POCKET_R);
    pGrad.addColorStop(0, "#000");
    pGrad.addColorStop(1, "transparent");
    ctx.beginPath();
    ctx.arc(p.x, p.y, POCKET_R, 0, Math.PI * 2);
    ctx.fillStyle = pGrad;
    ctx.fill();
  }

  // Head string line (faint)
  ctx.strokeStyle = "rgba(255,255,255,0.1)";
  ctx.lineWidth = 1;
  ctx.setLineDash([4, 6]);
  const headX = TABLE_W * 0.25;
  ctx.beginPath();
  ctx.moveTo(headX, CUSHION);
  ctx.lineTo(headX, TABLE_H - CUSHION);
  ctx.stroke();
  ctx.setLineDash([]);

  // Foot spot
  const footX = TABLE_W * 0.7;
  ctx.fillStyle = "rgba(255,255,255,0.15)";
  ctx.beginPath();
  ctx.arc(footX, TABLE_H / 2, 3, 0, Math.PI * 2);
  ctx.fill();

  // Draw balls
  for (const b of balls) {
    if (b.potted) continue;
    drawBall(b);
  }

  // Cue stick & aim line
  if (dragging && anyBallsMoving === false) {
    let cueBall = null;
    for (const b of balls) {
      if (!b.potted && b.cue) { cueBall = b; break; }
    }
    if (cueBall) {
      // Aim line (dotted, extending from cue ball in shot direction)
      const aimDx = dragStartX - dragEndX;
      const aimDy = dragStartY - dragEndY;
      const aimLen = Math.sqrt(aimDx * aimDx + aimDy * aimDy);
      if (aimLen > 5) {
        const aimNx = aimDx / aimLen;
        const aimNy = aimDy / aimLen;

        // Power indicator line from cue ball forward
        ctx.strokeStyle = "rgba(255,255,255,0.4)";
        ctx.lineWidth = 2;
        ctx.setLineDash([6, 4]);
        const powerFactor = Math.min(aimLen, 300) / 300;
        const aimDist = 100 + powerFactor * 200;
        ctx.beginPath();
        ctx.moveTo(cueBall.x, cueBall.y);
        ctx.lineTo(cueBall.x + aimNx * aimDist, cueBall.y + aimNy * aimDist);
        ctx.stroke();
        ctx.setLineDash([]);

        // Power indicator dots
        const dotCount = 5;
        for (let d = 1; d <= dotCount; d++) {
          const dd = aimDist * d / dotCount;
          ctx.fillStyle = `rgba(255,255,255,${0.15 + powerFactor * 0.3})`;
          ctx.beginPath();
          ctx.arc(cueBall.x + aimNx * dd, cueBall.y + aimNy * dd, 3, 0, Math.PI * 2);
          ctx.fill();
        }

        // Cue stick visual (behind the ball opposite to aim direction)
        const cueOffset = -BALL_R - 4;
        const cueLen = 180;
        const powerColor = `rgb(${Math.floor(50 + powerFactor * 205)}, ${Math.floor(200 - powerFactor * 100)}, ${Math.floor(50)})`;

        // Stick shadow
        ctx.strokeStyle = "rgba(0,0,0,0.3)";
        ctx.lineWidth = 14;
        ctx.beginPath();
        ctx.moveTo(cueBall.x - aimNx * cueOffset + 2, cueBall.y - aimNy * cueOffset + 2);
        ctx.lineTo(cueBall.x - aimNx * (cueOffset + cueLen) + 2, cueBall.y - aimNy * (cueOffset + cueLen) + 2);
        ctx.stroke();

        // Stick body
        ctx.strokeStyle = powerColor;
        ctx.lineWidth = 12;
        ctx.beginPath();
        ctx.moveTo(cueBall.x - aimNx * cueOffset, cueBall.y - aimNy * cueOffset);
        ctx.lineTo(cueBall.x - aimNx * (cueOffset + cueLen), cueBall.y - aimNy * (cueOffset + cueLen));
        ctx.stroke();

        // Stick tip
        ctx.fillStyle = "#8B4513";
        ctx.beginPath();
        const tipX = cueBall.x - aimNx * cueOffset;
        const tipY = cueBall.y - aimNy * cueOffset;
        ctx.arc(tipX, tipY, 6, 0, Math.PI * 2);
        ctx.fill();

        // Cue ferrule (white tip)
        ctx.fillStyle = "#f0e68c";
        ctx.beginPath();
        const ferrX = cueBall.x - aimNx * (cueOffset + 10);
        const ferrY = cueBall.y - aimNy * (cueOffset + 10);
        ctx.arc(ferrX, ferrY, 5, 0, Math.PI * 2);
        ctx.fill();

        // Power text
        const powerPct = Math.round(powerFactor * 100);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 14px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText(powerPct + "%", cueBall.x, cueBall.y - BALL_R - 20);
      }
    }
  }

  // Paused indicator
  if (paused && !dragging) {
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(0, 0, TABLE_W, TABLE_H);
    ctx.fillStyle = "#fff";
    ctx.font = "bold 32px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("PAUSED", TABLE_W / 2, TABLE_H / 2);
    ctx.font = "16px sans-serif";
    ctx.fillStyle = "#ccc";
    ctx.fillText("Press Resume to continue", TABLE_W / 2, TABLE_H / 2 + 35);
  }
}

function drawBall(b) {
  const x = b.x;
  const y = b.y;
  const r = BALL_R;

  // Shadow
  ctx.beginPath();
  ctx.arc(x + 2, y + 2, r, 0, Math.PI * 2);
  ctx.fillStyle = "rgba(0,0,0,0.3)";
  ctx.fill();

  // Ball body
  if (b.cue) {
    // Cue ball - white with subtle shading
    const grad = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r);
    grad.addColorStop(0, "#ffffff");
    grad.addColorStop(0.7, "#f0f0f0");
    grad.addColorStop(1, "#d0d0d0");
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.strokeStyle = "rgba(0,0,0,0.15)";
    ctx.lineWidth = 0.5;
    ctx.stroke();

    // Red dot on cue ball for spin indication
    ctx.beginPath();
    ctx.arc(x + r * 0.15, y - r * 0.1, 2, 0, Math.PI * 2);
    ctx.fillStyle = "rgba(200,0,0,0.5)";
    ctx.fill();
  } else {
    // Object ball with number circle
    const grad = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r);
    if (b.stripe) {
      // Stripe ball: white base with colored band
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = "#f5f5f0";
      ctx.fill();

      // Color band around middle
      ctx.save();
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.clip();
      const bandGrad = ctx.createLinearGradient(x - r, y, x + r, y);
      bandGrad.addColorStop(0, "transparent");
      bandGrad.addColorStop(0.35, b.color);
      bandGrad.addColorStop(0.65, b.color);
      bandGrad.addColorStop(1, "transparent");
      ctx.fillStyle = bandGrad;
      ctx.fillRect(x - r, y - r * 0.45, r * 2, r * 0.9);
      ctx.restore();

      // Number circle
      ctx.beginPath();
      ctx.arc(x, y, r * 0.42, 0, Math.PI * 2);
      ctx.fillStyle = "#f5f5f0";
      ctx.fill();
    } else {
      grad.addColorStop(0, lightenColor(b.color, 40));
      grad.addColorStop(0.7, b.color);
      grad.addColorStop(1, darkenColor(b.color, 40));
      ctx.beginPath();
      ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = grad;
      ctx.fill();

      // Number circle
      ctx.beginPath();
      ctx.arc(x, y, r * 0.42, 0, Math.PI * 2);
      ctx.fillStyle = "#f5f5f0";
      ctx.fill();
    }
    ctx.strokeStyle = "rgba(0,0,0,0.1)";
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.stroke();

    // Shine highlight
    ctx.beginPath();
    ctx.arc(x - r * 0.3, y - r * 0.3, r * 0.25, 0, Math.PI * 2);
    ctx.fillStyle = "rgba(255,255,255,0.35)";
    ctx.fill();
  }
}

function lightenColor(hex, amount) {
  let r = parseInt(hex.slice(1, 3), 16);
  let g = parseInt(hex.slice(3, 5), 16);
  let b = parseInt(hex.slice(5, 7), 16);
  r = Math.min(255, r + amount);
  g = Math.min(255, g + amount);
  b = Math.min(255, b + amount);
  return `rgb(${r},${g},${b})`;
}

function darkenColor(hex, amount) {
  let r = parseInt(hex.slice(1, 3), 16);
  let g = parseInt(hex.slice(3, 5), 16);
  let b = parseInt(hex.slice(5, 7), 16);
  r = Math.max(0, r - amount);
  g = Math.max(0, g - amount);
  b = Math.max(0, b - amount);
  return `rgb(${r},${g},${b})`;
}

function showPocketMsg(msg) {
  const el = document.getElementById("pocketed");
  el.textContent = msg;
  el.classList.add("show");
  if (pocketMsgTimer) clearTimeout(pocketMsgTimer);
  pocketMsgTimer = setTimeout(() => el.classList.remove("show"), 1200);
}

// ============ INPUT HANDLING ============
function getCueBall() {
  for (const b of balls) {
    if (!b.potted && b.cue) return b;
  }
  return null;
}

canvas.addEventListener("mousedown", function(e) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = TABLE_W / rect.width;
  const scaleY = TABLE_H / rect.height;
  const mx = (e.clientX - rect.left) * scaleX;
  const my = (e.clientY - rect.top) * scaleY;

  const cueBall = getCueBall();
  if (!cueBall || anyBallsMoving) return;

  const dx = mx - cueBall.x;
  const dy = my - cueBall.y;
  if (dx * dx + dy * dy < (BALL_R * 2.5) * (BALL_R * 2.5)) {
    dragging = true;
    dragStartX = mx;
    dragStartY = my;
    dragEndX = mx;
    dragEndY = my;
  }
});

canvas.addEventListener("mousemove", function(e) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = TABLE_W / rect.width;
  const scaleY = TABLE_H / rect.height;
  const mx = (e.clientX - rect.left) * scaleX;
  const my = (e.clientY - rect.top) * scaleY;

  if (!dragging) {
    // Check hover over cue ball
    const cueBall = getCueBall();
    mouseInCueBall = false;
    if (cueBall && !anyBallsMoving) {
      const dx = mx - cueBall.x;
      const dy = my - cueBall.y;
      mouseInCueBall = dx * dx + dy * dy < (BALL_R * 2.5) * (BALL_R * 2.5);
    }
